INSERT INTO kb_evidence (source_id, about_code, evidence_type, evidence_summary, direction, extraction_method, verification_status) VALUES (2, 'MC-001', 'empirical_study', 'همبستگی خیره‌کننده‌ای (بالای ۰/۹) میان اولویت‌های خبری رسانه‌های محلی و ملی و اولویت‌های ذهنی رأی‌دهندگان مردد در انتخابات ۱۹۶۸ ایالات متحده یافت شد.', 'neutral', 'ai_extraction', 'unverified');
