INSERT INTO kb_evidence (source_id, about_code, evidence_type, evidence_summary, direction, extraction_method, verification_status) VALUES (9, 'MC-105', 'bibliographic_reference', NULL, 'neutral', 'ai_extraction', 'unverified');
INSERT INTO kb_evidence (source_id, about_code, evidence_type, evidence_summary, direction, extraction_method, verification_status) VALUES (10, 'MC-105', 'empirical_study', 'نتایج نشان داد که تماشای صحنه‌های هیجانی (مانند خشونت یا ترس) پیش از مواجهه با یک محرک خنثی یا کم‌هیجان (مانند آگهی)، باعث افزایش شدت واکنش عاطفی و فیزیولوژیک به محرک دوم می‌شود، به‌ویژه زمانی که فاصله زمانی بین دو محرک کوتاه باشد.', 'neutral', 'ai_extraction', 'unverified');
INSERT INTO kb_evidence (source_id, about_code, evidence_type, evidence_summary, direction, extraction_method, verification_status) VALUES (11, 'MC-105', 'empirical_study', 'مشاهدات نشان می‌دهد که وقتی فرد پس از دیدن یک مستند ترسناک، به‌آسانی‌تر از محیط اطرافش می‌ترسد یا عصبانی می‌شود، نمونه‌ای عملی از انتقال برانگیختگی است؛ هیجان ایجادشده در رسانه به واقعیت بیرون منتقل شده و واکنش‌های بعدی را تقویت کرده است.', 'neutral', 'ai_extraction', 'unverified');
INSERT INTO kb_evidence (source_id, about_code, evidence_type, evidence_summary, direction, extraction_method, verification_status) VALUES (12, 'MC-106', 'bibliographic_reference', NULL, 'neutral', 'ai_extraction', 'unverified');
INSERT INTO kb_evidence (source_id, about_code, evidence_type, evidence_summary, direction, extraction_method, verification_status) VALUES (13, 'MC-106', 'bibliographic_reference', NULL, 'neutral', 'ai_extraction', 'unverified');
