INSERT INTO kb_evidence (source_id, about_code, evidence_type, evidence_summary, direction, extraction_method, verification_status) VALUES (15, 'MC-106', 'bibliographic_reference', NULL, 'neutral', 'ai_extraction', 'unverified');
INSERT INTO kb_evidence (source_id, about_code, evidence_type, evidence_summary, direction, extraction_method, verification_status) VALUES (16, 'MC-106', 'empirical_study', 'نشان دادند که مواجهه با بازی‌های ویدئویی خشن منجر به افزایش افکار، احساسات و برانگیختگی پرخاشگرانه در شرکت‌کنندگان می‌شود.', 'neutral', 'ai_extraction', 'unverified');
INSERT INTO kb_evidence (source_id, about_code, evidence_type, evidence_summary, direction, extraction_method, verification_status) VALUES (17, 'MC-106', 'empirical_study', 'برخی فراتحلیل‌ها اندازه اثر را ناچیز می‌دانند و استدلال می‌کنند که اثرات آزمایشگاهی لزوماً به خشونت واقعی در دنیای واقعی تعمیم نمی‌یابند.', 'neutral', 'ai_extraction', 'unverified');
