INSERT INTO kb_evidence (source_id, about_code, evidence_type, evidence_summary, direction, extraction_method, verification_status) VALUES (22, 'MC-108', 'empirical_study', 'نشان داد که ویژگی‌های فردی مانند سن و جنسیت، شدت اثرات رسانه‌ای را به‌طور معناداری تعدیل می‌کنند.', 'neutral', 'ai_extraction', 'unverified');
INSERT INTO kb_evidence (source_id, about_code, evidence_type, evidence_summary, direction, extraction_method, verification_status) VALUES (23, 'MC-108', 'empirical_study', 'تأیید کرد که استفاده یکسان از شبکه‌های اجتماعی برای برخی نوجوانان مفید و برای برخی مضر است، بسته به ویژگی‌های فردی و بافتی آن‌ها.', 'neutral', 'ai_extraction', 'unverified');
INSERT INTO kb_evidence (source_id, about_code, evidence_type, evidence_summary, direction, extraction_method, verification_status) VALUES (24, 'MC-011', 'bibliographic_reference', NULL, 'neutral', 'ai_extraction', 'unverified');
INSERT INTO kb_evidence (source_id, about_code, evidence_type, evidence_summary, direction, extraction_method, verification_status) VALUES (25, 'MC-011', 'empirical_study', 'اثبات تجربی اینکه با افزایش انتشار رسانه‌ای، شکاف دانش میان طبقات بالا و پایین افزایش می‌یابد.', 'neutral', 'ai_extraction', 'unverified');
INSERT INTO kb_evidence (source_id, about_code, evidence_type, evidence_summary, direction, extraction_method, verification_status) VALUES (26, 'MC-011', 'empirical_study', 'نشان دادن اینکه انگیزه و سودمندی ادراک‌شده می‌تواند نارسایی پایگاه اجتماعی را جبران کند و شکاف را کاهش دهد.', 'neutral', 'ai_extraction', 'unverified');
