INSERT INTO kb_evidence (source_id, about_code, evidence_type, evidence_summary, direction, extraction_method, verification_status) VALUES (30, 'MC-113', 'empirical_study', 'مطالعه‌ی اولیه‌ای که نشان داد چگونه الگوریتم‌های شخصی‌سازی و ساختار پلتفرم‌ها می‌توانند منجر به انزوا در حباب‌های اطلاعاتی و تضعیف گفت‌وگوی دموکراتیک شوند.', 'neutral', 'ai_extraction', 'unverified');
INSERT INTO kb_evidence (source_id, about_code, evidence_type, evidence_summary, direction, extraction_method, verification_status) VALUES (29, 'MC-113', 'empirical_study', 'یافته‌ها نشان دادند که اتاق‌های پژواک کامل بسیار نادرند و اکثر کاربران با منابع متنوعی در ارتباط هستند، هرچند تمایل به انتخاب منابع هم‌راستا وجود دارد.', 'neutral', 'ai_extraction', 'unverified');
