INSERT INTO kb_evidence (source_id, about_code, evidence_type, evidence_summary, direction, extraction_method, verification_status) VALUES (38, 'MC-012', 'empirical_study', 'مطالعه شهرستان اری (Erie County Study) نشان داد که اکثریت مردم تغییر رأی خود را ناشی از گفت‌وگو با افراد معتمد پیرامون خود می‌دانستند، نه مستقیماً از رسانه‌ها.', 'neutral', 'ai_extraction', 'unverified');
INSERT INTO kb_evidence (source_id, about_code, evidence_type, evidence_summary, direction, extraction_method, verification_status) VALUES (39, 'MC-012', 'empirical_study', 'این کتاب مدل دو مرحله‌ای را تدقیق کرد و ویژگی‌های رهبران افکار (هم‌سانی، مصرف رسانه‌ای بالا، موقعیت مرکزی در شبکه) را به صورت سیستماتیک تبیین نمود.', 'neutral', 'ai_extraction', 'unverified');
INSERT INTO kb_evidence (source_id, about_code, evidence_type, evidence_summary, direction, extraction_method, verification_status) VALUES (40, 'MC-128', 'bibliographic_reference', NULL, 'neutral', 'ai_extraction', 'unverified');
