INSERT INTO kb_evidence (source_id, about_code, evidence_type, evidence_summary, direction, extraction_method, verification_status) VALUES (45, 'MC-013', 'bibliographic_reference', NULL, 'neutral', 'ai_extraction', 'unverified');
INSERT INTO kb_evidence (source_id, about_code, evidence_type, evidence_summary, direction, extraction_method, verification_status) VALUES (46, 'MC-013', 'bibliographic_reference', NULL, 'neutral', 'ai_extraction', 'unverified');
INSERT INTO kb_evidence (source_id, about_code, evidence_type, evidence_summary, direction, extraction_method, verification_status) VALUES (46, 'MC-013', 'empirical_study', 'نشان داد که سردبیر تلکس (آقای گیتس) حدود ۹۰ درصد اخبار دریافتی را حذف می‌کند و معیارهای گزینش او عمدتا‌ً بر اساس ترجیحات فردی، دیدگاه سیاسی و سلایق اخلاقی شخصی است.', 'neutral', 'ai_extraction', 'unverified');
INSERT INTO kb_evidence (source_id, about_code, evidence_type, evidence_summary, direction, extraction_method, verification_status) VALUES (47, 'MC-013', 'empirical_study', 'مدل سلسله‌مراتب تأثیرات را ارائه داد و نشان داد که دروازه‌بانی تحت تأثیر پنج لایه از فردی تا نظام اجتماعی قرار دارد و نمی‌توان آن را صرفا‌ً به تصمیمات فردی تقلیل داد.', 'neutral', 'ai_extraction', 'unverified');
INSERT INTO kb_evidence (source_id, about_code, evidence_type, evidence_summary, direction, extraction_method, verification_status) VALUES (48, 'MC-132', 'bibliographic_reference', NULL, 'neutral', 'ai_extraction', 'unverified');
INSERT INTO kb_evidence (source_id, about_code, evidence_type, evidence_summary, direction, extraction_method, verification_status) VALUES (49, 'MC-134', 'bibliographic_reference', NULL, 'neutral', 'ai_extraction', 'unverified');
INSERT INTO kb_evidence (source_id, about_code, evidence_type, evidence_summary, direction, extraction_method, verification_status) VALUES (50, 'MC-134', 'empirical_study', 'این پژوهش بنیادین نشان داد که افراد پیام‌ها را نسبت به نگرش خود «هم‌راستا» (Assimilation) یا «تضاد» (Contrast) می‌کنند و این فرآیند تحت تأثیر درگیری اگو است.', 'neutral', 'ai_extraction', 'unverified');
INSERT INTO kb_evidence (source_id, about_code, evidence_type, evidence_summary, direction, extraction_method, verification_status) VALUES (51, 'MC-136', 'bibliographic_reference', NULL, 'neutral', 'ai_extraction', 'unverified');
INSERT INTO kb_evidence (source_id, about_code, evidence_type, evidence_summary, direction, extraction_method, verification_status) VALUES (52, 'MC-136', 'bibliographic_reference', NULL, 'neutral', 'ai_extraction', 'unverified');
INSERT INTO kb_evidence (source_id, about_code, evidence_type, evidence_summary, direction, extraction_method, verification_status) VALUES (53, 'MC-136', 'bibliographic_reference', NULL, 'neutral', 'ai_extraction', 'unverified');
INSERT INTO kb_evidence (source_id, about_code, evidence_type, evidence_summary, direction, extraction_method, verification_status) VALUES (54, 'MC-136', 'empirical_study', 'شناسایی و مستندسازی تجربی شش اصل بنیادین نفوذ و اثبات اثر آن‌ها در شرایط مختلف آزمایشگاهی و میدانی.', 'neutral', 'ai_extraction', 'unverified');
INSERT INTO kb_evidence (source_id, about_code, evidence_type, evidence_summary, direction, extraction_method, verification_status) VALUES (55, 'MC-136', 'empirical_study', 'ارائه مدل قابلیت بسط که با اصول نفوذ در تعامل است و بر نقش پردازش عمیق در برابر پردازش خودکار تأکید دارد.', 'neutral', 'ai_extraction', 'unverified');
