INSERT INTO kb_evidence (source_id, about_code, evidence_type, evidence_summary, direction, extraction_method, verification_status) VALUES (58, 'MC-138', 'empirical_study', 'آزمایش‌های آزمایشگاهی نشان دادند که منابع با تخصص و اطمینان‌پذیری بالاتر، تغییر نگرش بیشتری ایجاد می‌کنند، اما این اثر در بلندمدت کاهش می‌یابد.', 'neutral', 'ai_extraction', 'unverified');
