INSERT INTO kb_evidence (source_id, about_code, evidence_type, evidence_summary, direction, extraction_method, verification_status) VALUES (60, 'MC-014', 'empirical_study', 'پژوهش میدانی نشان داد که پایگاه طبقاتی به تنهایی نمی‌تواند نوع رمزگشایی را به صورت مکانیکی پیش‌بینی کند و عوامل دیگر نیز در تفسیر نقش دارند.', 'neutral', 'ai_extraction', 'unverified');
