INSERT INTO kb_evidence (source_id, about_code, evidence_type, evidence_summary, direction, extraction_method, verification_status) VALUES (70, 'MC-172', 'empirical_study', 'خرید استودیوهای تولید توسط پلتفرم‌های استریم به عنوان استراتژی کاهش وابستگی به محتوای بیرونی و بهره‌گیری از بهای مقیاس تفسیر می‌شود.', 'neutral', 'ai_extraction', 'unverified');
