INSERT INTO kb_evidence (source_id, about_code, evidence_type, evidence_summary, direction, extraction_method, verification_status) VALUES (80, 'MC-176', 'empirical_study', 'این مطالعه مبانی نظری بازارهای دوسویه را تبیین می‌کند و نشان می‌دهد که چگونه پلتفرم‌ها با کاهش هزینه تعامل میان دو گروه کاربر (مخاطب و تبلیغ‌دهنده) ارزش ایجاد می‌کنند. این یافته‌ها برای درک ساختار گروه‌های راهبردی در عصر دیجیتال حیاتی است.', 'neutral', 'ai_extraction', 'unverified');
