INSERT INTO kb_evidence (source_id, about_code, evidence_type, evidence_summary, direction, extraction_method, verification_status) VALUES (83, 'MC-191', 'empirical_study', 'بررسی ارائه بحران‌های کنگو، کوبا و قبرس در چهار روزنامه نروژی و شناسایی ۱۲ فاکتور ارزش خبری.', 'neutral', 'ai_extraction', 'unverified');
