INSERT INTO kb_evidence (source_id, about_code, evidence_type, evidence_summary, direction, extraction_method, verification_status) VALUES (94, 'MC-198', 'empirical_study', 'تبیین چارچوب تحلیلی تسخیر رسانه به عنوان تهدیدی برای دموکراسی و نشان‌دادن نقش ابزارهای مالی و مالکیتی در تضعیف استقلال تحریریه.', 'neutral', 'ai_extraction', 'unverified');
INSERT INTO kb_evidence (source_id, about_code, evidence_type, evidence_summary, direction, extraction_method, verification_status) VALUES (86, 'MC-198', 'empirical_study', 'تحلیل ساختاری خبر و نشان‌دادن اینکه چگونه خبر یک ساخته‌ی حرفه‌ای است که در معرض مداخلات ساختاری قرار دارد.', 'neutral', 'ai_extraction', 'unverified');
INSERT INTO kb_evidence (source_id, about_code, evidence_type, evidence_summary, direction, extraction_method, verification_status) VALUES (95, 'MC-198', 'empirical_study', 'بررسی رابطه بین اقتدار رسانه‌ای و ساختارهای قدرت و تأثیر آن بر استقلال حرفه‌ای.', 'neutral', 'ai_extraction', 'unverified');
