INSERT INTO kb_evidence (source_id, about_code, evidence_type, evidence_summary, direction, extraction_method, verification_status) VALUES (98, 'MC-002', 'empirical_study', 'تطابق حیرت‌انگیزی میان شبکه ماتریس رسانه‌ها و ماتریس تداعی‌های شناختی رأی‌دهندگان مشاهده شد؛ رسانه موفق شده بود نقشه مفهومی ذهن شهروندان را معماری کند.', 'neutral', 'ai_extraction', 'unverified');
