INSERT INTO kb_evidence (source_id, about_code, evidence_type, evidence_summary, direction, extraction_method, verification_status) VALUES (114, 'MC-222', 'empirical_study', 'نشان داد داده‌های شخصی هنگام تجمیع، به ابزاری برای تأثیر سیاسی خارج از آگاهی و رضایت فرد تبدیل می‌شوند.', 'neutral', 'ai_extraction', 'unverified');
