INSERT INTO kb_evidence (source_id, about_code, evidence_type, evidence_summary, direction, extraction_method, verification_status) VALUES (125, 'MC-024', 'empirical_study', 'فراتحلیل تأیید می‌کند که ارزیابی مقابله نقش قوی‌تری از ارزیابی تهدید در تبیین رفتار محافظتی دارد.', 'neutral', 'ai_extraction', 'unverified');
