INSERT INTO kb_evidence (source_id, about_code, evidence_type, evidence_summary, direction, extraction_method, verification_status) VALUES (139, 'MC-253', 'empirical_study', 'مدل ریاضی نشان داد که شبکه‌هایی با خوشه‌بندی بالا و فاصله کوتاه، با افزودن پیوندهای تصادفی به وجود می‌آیند.', 'neutral', 'ai_extraction', 'unverified');
