INSERT INTO kb_evidence (source_id, about_code, evidence_type, evidence_summary, direction, extraction_method, verification_status) VALUES (157, 'MC-257', 'empirical_study', 'پژوهش روی کاربران فیس‌بوک نشان داد که انتخاب‌های خود کاربران (هم‌سانی‌گزینی فعال) در محدود کردن مواجهه با دیدگاه مخالف نقشی بزرگ‌تر از رتبه‌بندی الگوریتمی پلتفرم داشت.', 'neutral', 'ai_extraction', 'unverified');
