INSERT INTO kb_evidence (source_id, about_code, evidence_type, evidence_summary, direction, extraction_method, verification_status) VALUES (159, 'MC-258', 'empirical_study', 'تحلیل عمیق از مفهوم عموم‌های شبکه‌ای و نحوه مدیریت هویت توسط نوجوانان در این فضاها.', 'neutral', 'ai_extraction', 'unverified');
