INSERT INTO kb_evidence (source_id, about_code, evidence_type, evidence_summary, direction, extraction_method, verification_status) VALUES (168, 'MC-262', 'empirical_study', 'نشان داد که تمرکز بر تجربه کاربری و شخصی‌سازی، نرخ ریزش را کاهش داده و درآمد تکرارشونده را افزایش می‌دهد.', 'neutral', 'ai_extraction', 'unverified');
