INSERT INTO kb_evidence (source_id, about_code, evidence_type, evidence_summary, direction, extraction_method, verification_status) VALUES (199, 'MC-003', 'empirical_study', 'این پژوهش کلاسیک نشان داد که اخبار تلویزیونی با برجسته‌سازی حوزه‌های مختلف (مانند سیاست خارجی یا اقتصاد)، معیارهای قضاوت مخاطبان درباره عملکرد رئیس‌جمهور را به‌طور معناداری تغییر می‌دهد.', 'neutral', 'ai_extraction', 'unverified');
INSERT INTO kb_evidence (source_id, about_code, evidence_type, evidence_summary, direction, extraction_method, verification_status) VALUES (202, 'MC-003', 'empirical_study', 'ارائه مدل نظری فعال‌سازی گسترده که مبنای شناختی پرایمینگ است و نشان داد چگونه تحریک یک مفهوم، مفاهیم مرتبط را در حافظه فعال می‌سازد.', 'neutral', 'ai_extraction', 'unverified');
