INSERT INTO kb_evidence (source_id, about_code, evidence_type, evidence_summary, direction, extraction_method, verification_status) VALUES (113, 'MC-300', 'bibliographic_reference', NULL, 'neutral', 'ai_extraction', 'unverified');
INSERT INTO kb_evidence (source_id, about_code, evidence_type, evidence_summary, direction, extraction_method, verification_status) VALUES (205, 'MC-300', 'empirical_study', 'کاربری که پس از جست‌وجوی یک محصول، آگهی آن را در شبکه‌ی اجتماعی می‌بیند، در پشت صحنه با سیستمی از پروفایل‌سازی بر پایه‌ی میلیون‌ها تعامل روبه‌روست.', 'neutral', 'ai_extraction', 'unverified');
INSERT INTO kb_evidence (source_id, about_code, evidence_type, evidence_summary, direction, extraction_method, verification_status) VALUES (206, 'MC-300', 'empirical_study', 'داده‌های شخصی، هنگامی که تجمیع می‌شوند، به ابزاری برای تأثیر سیاسی خارج از آگاهی و رضایت فرد تبدیل می‌شوند.', 'neutral', 'ai_extraction', 'unverified');
INSERT INTO kb_evidence (source_id, about_code, evidence_type, evidence_summary, direction, extraction_method, verification_status) VALUES (207, 'MC-300', 'empirical_study', 'امتیازی که بر رفتار شهروند ثبت می‌شود، به دسترسی او به خدمات، سفر و حتی مسکن ربط داده می‌شود و منطق نظارت مبتنی بر داده را در حدّ نهایی نشان می‌دهد.', 'neutral', 'ai_extraction', 'unverified');
INSERT INTO kb_evidence (source_id, about_code, evidence_type, evidence_summary, direction, extraction_method, verification_status) VALUES (208, 'MC-300', 'empirical_study', 'فیلم‌برداری شهروندان از پلیس و نهادهای قدرتمند با گوشی نشان می‌دهد که نگاه دیگر یک‌طرفه نیست و ساختارهای نظارتی همواره مورد چالش و بازنشانی هستند.', 'neutral', 'ai_extraction', 'unverified');
INSERT INTO kb_evidence (source_id, about_code, evidence_type, evidence_summary, direction, extraction_method, verification_status) VALUES (209, 'MC-300', 'empirical_study', 'وقتی فید الگوریتمی به کاربر صرفاً محتوایی هم‌سو با باورهای پیشینش نشان می‌دهد، نوعی سانسور الگوریتمی رخ می‌دهد که ادراک جهان کاربر را بدون آگاهی او شکل می‌دهد.', 'neutral', 'ai_extraction', 'unverified');
INSERT INTO kb_evidence (source_id, about_code, evidence_type, evidence_summary, direction, extraction_method, verification_status) VALUES (210, 'MC-300', 'empirical_study', 'تنظیمات پیچیده و پر از پیش‌فرض نشان می‌دهد «انتخاب»ی که به کاربر پیشنهاد می‌شود گاه انتخابی صوری است و قدرت واقعی تصمیم در دست طراح پلتفرم می‌ماند.', 'neutral', 'ai_extraction', 'unverified');
