INSERT INTO kb_evidence (source_id, about_code, evidence_type, evidence_summary, direction, extraction_method, verification_status) VALUES (287, 'MC-383', 'empirical_study', 'بنیان‌ریزی چارچوب نظری برای درک تعاملات میان دو گروه کاربر در پلتفرم‌ها که مبنای اقتصادی مدل‌های رسانه‌ای مدرن است.', 'neutral', 'ai_extraction', 'unverified');
