INSERT INTO kb_evidence (source_id, about_code, evidence_type, evidence_summary, direction, extraction_method, verification_status) VALUES (293, 'MC-039', 'empirical_study', 'مطرح‌کننده‌ی چارچوب نوآوری مخرب و تحلیل انگیزه‌های سازمانی بنگاه‌های مستقر در برابر نوآوری‌های کم‌ارزش‌تر.', 'neutral', 'ai_extraction', 'unverified');
INSERT INTO kb_evidence (source_id, about_code, evidence_type, evidence_summary, direction, extraction_method, verification_status) VALUES (294, 'MC-039', 'empirical_study', 'نقد نظریه نوآوری مخرب به دلیل انتخاب موردی و تعریف مبهم؛ بسیاری از «مخرب‌ها» از ابتدا خدمت کاملااً متفاوت یا پیشرفته‌تر ارائه دادند، نه ساده‌تر.', 'neutral', 'ai_extraction', 'unverified');
