INSERT INTO kb_evidence (source_id, about_code, evidence_type, evidence_summary, direction, extraction_method, verification_status) VALUES (301, 'MC-004', 'empirical_study', 'ارائه مفهوم چارچوب‌ها به عنوان طرح‌واره‌های تفسیری که به انسان‌ها امکان می‌دهند اطلاعات پیرامون خود را سازمان دهند و موقعیت‌ها را معنادار کنند.', 'neutral', 'ai_extraction', 'unverified');
INSERT INTO kb_evidence (source_id, about_code, evidence_type, evidence_summary, direction, extraction_method, verification_status) VALUES (302, 'MC-004', 'empirical_study', 'فرمول‌بندی عملیاتی چارچوب‌بندی به عنوان گزینش و برجسته‌سازی اجزای متن؛ ارائه چهار کارکرد بنیادین چارچوب (تعریف مسئله، تشخیص علت، داوری اخلاقی، پیشنهاد راه‌حل).', 'neutral', 'ai_extraction', 'unverified');
INSERT INTO kb_evidence (source_id, about_code, evidence_type, evidence_summary, direction, extraction_method, verification_status) VALUES (303, 'MC-004', 'empirical_study', 'تمایز میان چارچوب‌های اپیزودیک (فردمحور) و موضوعی (ساختارمحور) در اخبار تلویزیونی؛ نشان دادن اینکه چارچوب‌های اپیزودیک مسئولیت را متوجه فرد می‌سازند و چارچوب‌های موضوعی مسئولیت را متوجه ساختارها.', 'neutral', 'ai_extraction', 'unverified');
