-- 7.1) افزودنیِ نمایشی: برچسب فارسیِ جهت معکوس (در الگوی پایه ذخیره نمی‌شد)
ALTER TABLE kb_relation_types ADD COLUMN inverse_label_fa VARCHAR(200) NULL AFTER inverse_code;
UPDATE kb_relation_types SET inverse_label_fa = CASE code
  WHEN 'ADDRESSES' THEN 'پاسخ‌گفته در'
  WHEN 'AGGREGATED_INTO' THEN 'تجمیع‌کننده‌ی'
  WHEN 'ANALYZES' THEN 'تحلیل‌شده توسط'
  WHEN 'ANALYZED_IN' THEN 'تحلیل‌کننده‌ی'
  WHEN 'ANSWERED_BY' THEN 'پاسخ‌دهنده به'
  WHEN 'APPLIES_TO' THEN 'دارای کاربردِ'
  WHEN 'AUTHORED_BY' THEN 'تألیف‌کننده‌ی'
  WHEN 'BASED_ON' THEN 'مبنای'
