  WHEN 'FORMULATED_BY' THEN 'صورت‌بندی‌کننده‌ی'
  WHEN 'GOVERNS' THEN 'تحت نظارتِ'
  WHEN 'GUIDED_BY' THEN 'هدایت‌کننده‌ی'
  WHEN 'HAS_BRANCH' THEN 'شاخه‌ای از'
