  WHEN 'HAS_PARTICIPANT' THEN 'شرکت‌کننده در'
  WHEN 'HAS_PROPOSITION' THEN 'گزاره‌ای از'
  WHEN 'HAS_SUBFIELD' THEN 'زیرمجموعه‌ی'
  WHEN 'IMPLEMENTED_THROUGH' THEN 'پیاده‌سازنده‌ی'
  WHEN 'INCLUDED_IN' THEN 'شاملِ'
  WHEN 'INDICATES' THEN 'سنجیده‌شده با'
  WHEN 'INFLUENCED' THEN 'متأثر از'
  WHEN 'INFLUENCED_BY' THEN 'تأثیرگذار بر'
  WHEN 'IS_A' THEN 'دارای زیرنوع'
  WHEN 'JUSTIFIED_BY' THEN 'توجیه‌کننده‌ی'
  WHEN 'MEASURES' THEN 'سنجیده‌شده با'
  WHEN 'MEMBER_OF' THEN 'دارای عضوِ'
  WHEN 'MOTIVATED_BY' THEN 'انگیزه‌بخشِ'
  WHEN 'OPERATIONALIZES' THEN 'عملیاتی‌شده توسط'
  WHEN 'PART_OF' THEN 'شاملِ جزء'
  WHEN 'PRODUCED_BY' THEN 'تولیدکننده‌ی'
  WHEN 'PROPOSED_BY' THEN 'ارائه‌دهنده‌ی'
  WHEN 'PUBLISHED_BY' THEN 'ناشرِ'
  WHEN 'REFUTED_BY' THEN 'ردکننده‌ی'
  WHEN 'REPLACED_BY' THEN 'جایگزین می‌کند'
  WHEN 'REPLICATES' THEN 'تکرارشده توسط'
  WHEN 'REPORTED_IN' THEN 'گزارش‌کننده‌ی'
